import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const API_URL = "http://localhost:5001/api/products";

const ShopPage = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    fetch(API_URL)
      .then((res) => {
        if (!res.ok) throw new Error("Gagal mengambil produk");
        return res.json();
      })
      .then((data) => {
        setProducts(data);
        setError(null);
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="max-w-7xl mx-auto py-12 px-4">
      <h1 className="text-3xl font-bold mb-8">Semua Produk</h1>
      {loading && <div>Memuat produk...</div>}
      {error && <div className="text-red-500">{error}</div>}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-8">
        {products.map((product) => (
          <Link to={`/shop/${product.id}`} key={product.id} className="block border rounded-lg shadow hover:shadow-lg transition p-4 bg-white">
            <img src={product.image} alt={product.name} className="w-full h-48 object-contain rounded mb-3 bg-gray-100" />
            <div className="font-semibold text-lg mb-1">{product.name}</div>
            <div className="text-blue-600 font-bold mb-2">Rp {product.price.toLocaleString("id-ID")}</div>
            <div className="text-gray-500 text-sm line-clamp-2">{product.description}</div>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default ShopPage;
